"""Standalone source/paint comparison on one explicit clock; no bone transfer."""
import base64,json
from pathlib import Path
P=Path(__file__).resolve().parent;source=json.loads((P/'source/source.json').read_text());case=json.loads((P/'image-case.json').read_text());report=json.loads((P/'surface-review.json').read_text())
def image(path):return 'data:image/png;base64,'+base64.b64encode(Path(path).read_bytes()).decode()
payload={'source':source,'case':case,'report':report,'source_images':[image(f['path']) for f in source['frames']],'paint_images':[image(f['path']) for f in case['frames']]}
html='''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pickup source vs paint review</title>
<style>body{background:#162031;color:#eef2fa;font:15px system-ui;margin:20px}button,select,input{font:inherit}canvas{width:min(384px,43vw);height:auto;background:#273343;border:1px solid #718097}button,select{padding:8px;background:#304058;color:white;border:1px solid #748297}main{display:flex;gap:20px;flex-wrap:wrap}figure{margin:0}#frames{width:min(800px,90vw)}pre{white-space:pre-wrap}small{display:block;max-width:850px;color:#c2cce0}</style>
<h1>Pickup8: source vs original paint</h1><p id="verdict">REVIEW ONLY — planted feet and recovery timing still fail. Anatomy/parts/production not approved.</p>
<main><figure><figcaption>Actual external CC0 source / named bones</figcaption><canvas id="source" width="384" height="512"></canvas></figure><figure><figcaption>Our generated character / visible surfaces only</figcaption><canvas id="paint" width="384" height="512"></canvas></figure></main>
<p id="time"></p><input id="frames" type="range" min="0" max="7" value="0"><p><button id="prev">←</button> <button id="play">Play once</button> <button id="next">→</button> <label><input id="grid" type="checkbox" checked>32px grid</label> <label><input id="points" type="checkbox" checked>Source bones / image surface points</label></p>
<small>One-shot action sampled at8 source times over1300ms, plus authored600ms terminal review pause. Source model and painted body proportions differ; side-by-side observations are not a recovered skeleton. All images retain fixed canvas/scale; painted lower row has one declared32px origin repair, no per-frame fitting. White image markers are toe-cap/cuff surfaces, not anatomical joints. Manual observation uncertainty is3–6px; source phase is a diagnostic.</small><pre id="issues"></pre>
<script>const P=__DATA__, $=id=>document.getElementById(id);let key=0,running=false,start=0,offset=0;const images={};for(const kind of ['source','paint'])images[kind]=P[kind+'_images'].map(src=>{let im=new Image;im.onload=draw;im.src=src;return im});
function draw(){for(const kind of ['source','paint']){const c=$(kind),ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);if(images[kind][key].complete)ctx.drawImage(images[kind][key],0,0);if($('grid').checked){ctx.strokeStyle='#8393a466';ctx.lineWidth=.5;for(let x=0;x<384;x+=32){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,512);ctx.stroke()}for(let y=0;y<512;y+=32){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(384,y);ctx.stroke()}}if($('points').checked){let ps=kind==='source'?P.source.frames[key].points:P.case.frames[key].observations;for(let[n,p]of Object.entries(ps)){if(!p.xy)continue;ctx.strokeStyle=kind==='source'?(n.startsWith('right.')?'#369bff':n.startsWith('left.')?'#ff9d3b':'#a3afc5'):'#ffffff';ctx.beginPath();ctx.arc(...p.xy,4,0,Math.PI*2);ctx.stroke()}}}
$('frames').value=key;$('time').textContent='Frame '+(key+1)+' / '+P.case.frames[key].time_ms.toFixed(2)+'ms';$('issues').textContent=JSON.stringify({frame_issues:P.report.issues.filter(x=>x.frame===key||x.marker),production_pass:false},null,2)}
function set(i){running=false;key=Math.max(0,Math.min(7,i));draw()}
$('frames').oninput=()=>set(+$('frames').value);$('prev').onclick=()=>set(key-1);$('next').onclick=()=>set(key+1);$('grid').onchange=$('points').onchange=draw;
function tick(now){if(!running)return;let time=offset+now-start;while(key<7&&P.case.frames[key+1].time_ms<=time)key++;draw();if(time>=1900){running=false;return}requestAnimationFrame(tick)}
$('play').onclick=()=>{if(running){running=false;return}if(key===7)key=0;offset=P.case.frames[key].time_ms;start=performance.now();running=true;requestAnimationFrame(tick)};
window.pickupReview={get frame(){return key},get running(){return running},set};draw();</script>'''
(P/'source-vs-paint.html').write_text(html.replace('__DATA__',json.dumps(payload,separators=(',',':')).replace('<','\\u003c')))
print('REVIEW_BUILT')
